public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] t = new int[n];
        for (int i = 0; i < n; i++) {
            t[i] = scanner.nextInt();
        }

        // Sort the array to easily check consecutive differences
        Arrays.sort(t);

        boolean found = false;
        // Check all possible triplets of distinct indices
        // Since n is small (<= 50), O(n^3) is acceptable
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    int a = t[i];
                    int b = t[j];
                    int c = t[k];

                    // Rule 1: No two friends can get balls of the same size
                    if (a == b || b == c || a == c) {
                        continue;
                    }

                    // Rule 2: No two friends can get balls of sizes that differ by more than 2
                    // This means max(a,b,c) - min(a,b,c) <= 2
                    int minSize = Math.min(a, Math.min(b, c));
                    int maxSize = Math.max(a, Math.max(b, c));

                    if (maxSize - minSize <= 2) {
                        found = true;
                        break;
                    }
                }
                if (found) break;
            }
            if (found) break;
        }

        if (found) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }
}
